using System;using System.Linq;using System.Reflection;using System.Collections.Generic;using Sunward;using Sunward.Remaster;using UnityEngine;
static class HeavenAudioPolishTests
{
 static int n;static BindingFlags f=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool b,string s){n++;if(!b)throw new Exception(s);}
 static T Get<T>(object o,string k)=>(T)o.GetType().GetField(k,f).GetValue(o);
 static void Set(object o,string k,object v)=>o.GetType().GetField(k,f).SetValue(o,v);
 static void Call(object o,string m,params object[] args)=>o.GetType().GetMethod(m,f).Invoke(o,args);
 public static void Run()
 {
  var crop=new FarmCrop();Call(crop,"Awake");crop.SetSoilHeight(.8f);crop.Harvest();crop.Bloom();Check(Math.Abs(crop.transform.position.y-.8f)<.001f,"Crop regrows under the deeper soil");
  var g=new GameFlow{Player=new WolfMotor(),Health=100,Panel=""};g.Player.game=g;var h=new HeavenlyGarden{game=g};
  foreach(float x in new[]{-2.2f,0,2.2f})foreach(float z in new[]{-1.3f,0,1.3f})Check(HeavenReturnPortal.Contains(new Vector3(x,.1f,z)),"Visible local gate opening does not return");
  Check(!HeavenReturnPortal.Contains(new Vector3(3.5f,.1f,0)),"Standing beside gate returns home");var portal=new HeavenReturnPortal{game=g};portal.transform.position=HeavenlyGarden.Centre+new Vector3(0,0,-26.5f);g.Player.transform.position=portal.transform.position+Vector3.up*.1f;Call(portal,"Update");Check(g.homeReturns==1,"Gate-owned Update does not call home");
  var body=new NativeAmaterasu();Call(body,"Awake");body.ApplyPowerForm(1);var ribbons=new SpectralTendrils();Set(ribbons,"native",body);Time.unscaledDeltaTime=.1f;Call(ribbons,"LateUpdate");Check(Get<NativePaintedRig[]>(ribbons,"rigs")==null,"Second form builds/displays ES ribbons");body.ApplyPowerForm(2);Call(ribbons,"LateUpdate");Check(Get<NativePaintedRig[]>(ribbons,"rigs").All(r=>r.Root.activeSelf),"Third form lacks ribbons");body.ApplyPowerForm(1);Call(ribbons,"LateUpdate");Check(Get<NativePaintedRig[]>(ribbons,"rigs").All(r=>!r.Root.activeSelf),"Returning to second form leaves ribbons visible");
  var bank=new NativePoseBank("Okami/es4a/Poses");foreach(string name in new[]{"et03_002","et03_003"}){var c=bank.Find(name);Check(c.Loop,"Ribbon uses non-looping power-up curve");for(int b=0;b<bank.BoneCount;b++){var a=c.Rotation[b];var z=c.Rotation[(c.Samples-1)*bank.BoneCount+b];Check(Math.Abs(a.x-z.x)+Math.Abs(a.y-z.y)+Math.Abs(a.z-z.z)<.002f,"Native wind seam snaps");Check(c.Scale.All(s=>(s-Vector3.one).magnitude<.001f),"Ribbon stretches like rubber");}}
  var audio=new ValleyAudio();Set(audio,"game",g);var aSource=new AudioSource();Set(audio,"palaceMusic",aSource);var bSource=new AudioSource();Set(audio,"palaceTail",bSource);Get<HashSet<AudioSource>>(audio,"musical").Add(aSource);Get<HashSet<AudioSource>>(audio,"musical").Add(bSource);Get<Dictionary<string,List<AudioClip>>>(audio,"bank")["palacemusic"]=new List<AudioClip>{new AudioClip{length=4}};Time.unscaledDeltaTime=1;Call(audio,"FadePalace",.004f);Check(aSource.isPlaying&&aSource.loop,"Palace waveform does not loop on the mixer");aSource.time=3;Call(audio,"FadePalace",.004f);Check(!bSource.isPlaying,"Frame-timed second voice restarts the seam");Check(Math.Abs(aSource.volume-.004f)<.0001f,"Palace music did not use the quieter gain");
  var effect=new AudioSource();Call(audio,"Level",effect,.6f);GameAudioSettings.Set(1,0);GameAudioSettings.Set(2,0);Call(audio,"LateUpdate");Check(effect.volume==0&&bSource.volume==0,"Volume controls do not mute both categories");GameAudioSettings.Set(1,.5f);GameAudioSettings.Set(2,.25f);for(int i=0;i<3;i++)Call(audio,"LateUpdate");Check(Math.Abs(effect.volume-.15f)<.0001f&&Math.Abs(aSource.volume-.002f)<.0001f,"Volume cannot recover from zero or compounds each frame");GameAudioSettings.Set(0,.4f);Check(Math.Abs(AudioListener.volume-.4f)<.001f,"Master volume does not control listener");GameAudioSettings.Save();typeof(GameAudioSettings).GetField("loaded",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,false);Check(Math.Abs(GameAudioSettings.Master-.4f)<.001f&&Math.Abs(GameAudioSettings.Music-.5f)<.001f,"Volume preferences not restored through PlayerPrefs API");GameAudioSettings.Set(0,1);GameAudioSettings.Set(1,1);GameAudioSettings.Set(2,1);Call(audio,"FadePalace",0f);Call(audio,"FadePalace",0f);Check(!aSource.isPlaying&&!bSource.isPlaying,"Crossfade keeps music playing after exit");
  Console.WriteLine("PASS "+n+" actual torii return, third-form-only seamless ribbons, quiet music crossfade and persistent category-volume contracts; engine doubles, not Unity");
 }
}
